//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS00100.xml";
scwin.vMktactCd = "113";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "1";
scwin.vRowCount = 0;
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vProcsStatCd;
scwin.vRegYn = 'N';
scwin.vRowPos = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
//var vStrtDd = '';


/********************************************** 
 * 함수명   : fn_list_sync
 * 설명       : 신청/접수 목록을 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; //시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == '1') {
        $c.cm.ShowWin(grd_ApplList);
    } else {
        $c.cm.ShowWin(grd_AcptList);
    }
};



/********************************************** 
 * 함수명   : fn_SetMktactCd
 * 설명       : 신규상장 채권시장조치구분코드를 설정한다.
 ***********************************************/
scwin.fn_SetMktactCd = function() {
    //숨기기
    $c.stf.showObj(label_47, false);
    $c.stf.showObj(cmb_MunibndTpCd, false);
    var screenId = $c.stf.InfoMenuID();

    //국채 WIT 지정 jackal_15.09.17
    if (screenId == "BNS00100") {
        scwin.vMktactCd = "113";
        $c.stf.setObjectValue(cmb_BndTpCd, 'GB');
        cmb_BndTpCd.setDisabled(true);
        $c.stf.setObjectValue(cmb_PresaleGovbndTrdTpCd, '1');
        cmb_PresaleGovbndTrdTpCd.setDisabled(true);
        $c.stf.setObjectValue(cmb_CoupnRtFinalYn, 'N');
        cmb_CoupnRtFinalYn.setDisabled(true);
        $c.stf.setObjectValue(edt_CoupnRt, 0);
        edt_CoupnRt.Enable2 = false;
    }
    //국채 개별상장 
    else if (screenId == "BNS00000") {
        scwin.vMktactCd = "111";
        $c.stf.setObjectValue(cmb_BndTpCd, 'GB');
        cmb_BndTpCd.setDisabled(true);
    }
    //지방채
    else if (screenId == "BNS01000") {
        scwin.vMktactCd = "121";
        $c.stf.showObj(label_47, true);
        $c.stf.showObj(cmb_MunibndTpCd, true);
        $c.stf.setObjectValue(cmb_BndTpCd, 'MB');
        cmb_BndTpCd.setDisabled(true);
    }
    //특수채 개별상장
    else if (screenId == "BNS02000") {
        scwin.vMktactCd = "131";
        $c.stf.setObjectValue(cmb_BndTpCd, 'AB');
        cmb_BndTpCd.setDisabled(true);
    }
    //회사채 개별상장
    else if (screenId == "BNS03000") {
        scwin.vMktactCd = "141";
        $c.stf.setObjectValue(cmb_BndTpCd, 'CO');
        cmb_BndTpCd.setDisabled(true);
    }
    //외국채권 개별상장
    else if (screenId == "BNS04000") {
        scwin.vMktactCd = "151";
        $c.stf.setObjectValue(cmb_BndTpCd, 'FO');
        cmb_BndTpCd.setDisabled(true);
    }
};



