/********************************************** 
 * 함수명   : fn_MinusGumriOK
 * JACKAL_191129
 * 설명       : 개별 체크한다.
 ***********************************************/
scwin.fn_MinusGumriOK = function(obj, msg) {
    var obj_rt = $c.stf.getObjectValue(obj);
    if (obj_rt < 0) {
        if (!window.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?')) {
            //setObjectValue(obj, obj_rt*(-1));
            obj.focus();
            return 1;
        }
    }
};





/********************************************** 
* 함수명   : fn_MinusGumriCheck
* JACKAL_191129
* 설명       : 개별 체크한다.
edt_CoupnRt COUPN_RT
edt_ScbdInt SCBD_INT
edt_BkHoldyDdPrincAcrintRt BK_HOLDY_DD_PRINC_ACRINT_RT
edt_BkHoldyDdIntCmpAcrintRt   BK_HOLDY_DD_INT_CMP_ACRINT_RT
edt_GrtYd GRT_YD
edt_AddYd ADD_YD
***********************************************/
scwin.fn_MinusGumriCheck = function() {
    if (!scwin.fn_MinusGumriOK(edt_CoupnRt, '표면이자율') &&
        !scwin.fn_MinusGumriOK(edt_ScbdInt, '낙찰금리') &&
        !scwin.fn_MinusGumriOK(edt_BkHoldyDdPrincAcrintRt, '휴무(원금)경과금리') &&
        !scwin.fn_MinusGumriOK(edt_BkHoldyDdIntCmpAcrintRt, '휴무(이자)경과금리') &&
        !scwin.fn_MinusGumriOK(edt_GrtYd, '보장수익률') &&
        !scwin.fn_MinusGumriOK(edt_AddYd, '추가수익률')) return 1;

    else return 0;
};


/********************************************** 
 * 함수명   : fn_CheckEach
 * 설명       : 개별 체크한다.
 ***********************************************/
scwin.fn_CheckEach = function() {
    //상장일이 발행일보다 빠른 경우 체크
    //if(dts_IsuInfo.NameValue(1, "LIST_DD") < dts_IsuInfo.NameValue(1, "ISU_DD")) {
    //	if (! window.confirm('상장일이 발행일 이전입니다.\n그래도 처리하시겠습니까?')) return 1;
    //}

    //수정 or 처리완료
    if (scwin.processGp == '3' || scwin.processGp == '4') {
        // 마이너스 금리 체크 (접수시는 값변경이 안됨)  수정 및 처리완료 시에만 체크하도록 수정
        if (!scwin.fn_MinusGumriCheck()) return 1; // JACKAL_191129

        //상환방법: 영구채 선택시 상환일: 9999-12-31 이여야함.
        if ($c.stf.getObjectValue(cmb_RedmptMethdTpCd) == "3" && $c.stf.getObjectValue(edt_RedmptDd) != "99991231") {
            $c.win.alert("상환방법이 영구채 일 경우 상환일은 반드시 [9999-12-31]이여야 합니다.");
            edt_RedmptDd.focus();
            return 1;
        }
        // 상환일: 9999-12-31 선택시 상환방법: 영구채 이여야함.
        if ($c.stf.getObjectValue(edt_RedmptDd) == "99991231" && $c.stf.getObjectValue(cmb_RedmptMethdTpCd) != "3") {
            $c.win.alert("상환일이 [9999-12-31] 일 경우 상환방법은 반드시 영구채이여야 합니다.");
            cmb_RedmptMethdTpCd.focus();
            return 1;
        }
        if ($c.stf.getObjectValue(cmb_RedmptMethdTpCd) == "3") {
            //상환방법: 영구채 선택시 비정기 선택해야 함. JACKAL_190509
            //if (getObjectValue(cmb_RedmptMethdTpCd) == "3" )
            //{
            //	var cd = getObjectValue(cmb_IntDecsnRegulYn);	
            //	// 금리결정 정기이면  
            //	if(cd == 'Y') 
            //	{
            //		alert("상환방법이 영구채 일 경우 변동금리 탭화면의 금리결정정기여부를 비정기로 선택하여야 합니다.");
            //		return 1;
            //	}
            //}

            if (!window.confirm("영구채로 처리하시겠습니까?")) {
                return 1;
            } else {
                return false;
            }
        }
    }

    //처리완료 시 체크
    if (scwin.processGp == '3') {
        //표면이자율 체크
        if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") == '') {
            $c.win.alert("표면이자율 확정여부를 선택하십시오.");
            return 1;
        } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") == 'Y' &&
            dts_IsuInfo.getCellData(1, "COUPN_RT") == '') {
            $c.win.alert("표면이자율 확정시에는 표면이자율을 입력하십시오.");
            return 1;
        } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") == 'N' &&
            dts_IsuInfo.getCellData(1, "COUPN_RT") != '') {
            if (!window.confirm('표면이자율이 미확정입니다.\n그래도 처리하시겠습니까?')) return 1;
        }
    }

    //이미 접수중인지 체크
    if (scwin.vBndListProcsTpCd == '1' &&
        $c.stf.getObjectValue(txb_StdCd) != '') {
        var qryId = 'lds.stf.bnsnew.select.listCheckNewListAcpt';
        var dsNm = 'BNS_CHECK_ITEM';
        var param = '&{P}V_STD_CD=' + $c.stf.getObjectValue(txb_StdCd);
        dts_CheckCmData.SyncLoad = true;
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckCmData, dsNm, qryId, param);
        if (dts_CheckCmData.getTotalRow() > 0) {
            var id = dts_CheckCmData.getCellData(1, 'BND_APPL_ID');
            var dd = dts_CheckCmData.getCellData(1, 'STRT_DD');
            if (dts_CheckCmData.getCellData(1, 'APPL_YN') == 'Y') {
                $c.win.alert("이미 접수번호 " + id + " : 적용일 " + dd + "로 시장조치되었습니다.");
                return 1;
            } else {
                $c.win.alert("이미 접수번호 " + id + " : 적용일 " + dd + "로 처리중이므로 접수가 불가능합니다.");
                return 1;
            }
        }
    }
    if (scwin.vBndListProcsTpCd == '2') {
        //신용기관체크
        var creditMsg = '신용평가기관을 선택하지 않으셨습니다.';
        var creditMsg1 = '신용등급을 선택하지 않으셨습니다.';
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd1) == '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd1) != '') {
            $c.win.alert(creditMsg);
            cmb_CreditValuInstCd1.focus();
            return 1;
        } else if ($c.stf.getObjectValue(cmb_CreditValuInstCd1) != '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd1) == '') {
            $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd1.focus();
            return 1;
        }
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd2) == '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd2) != '') {
            $c.win.alert(creditMsg);
            cmb_CreditValuInstCd2.focus();
            return 1;
        } else if ($c.stf.getObjectValue(cmb_CreditValuInstCd2) != '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd2) == '') {
            $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd2.focus();
            return 1;
        }
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd3) == '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd3) != '') {
            $c.win.alert(creditMsg);
            cmb_CreditValuInstCd3.focus();
            return 1;
        } else if ($c.stf.getObjectValue(cmb_CreditValuInstCd3) != '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd3) == '') {
            $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd3.focus();
            return 1;
        }
        if ($c.stf.getObjectValue(cmb_CreditValuInstCd4) == '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd4) != '') {
            $c.win.alert(creditMsg);
            cmb_CreditValuInstCd4.focus();
            return 1;
        } else if ($c.stf.getObjectValue(cmb_CreditValuInstCd4) != '' &&
            $c.stf.getObjectValue(cmb_ByinstCreditValuGrd4) == '') {
            $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd4.focus();
            return 1;
        }

        //발행용도 총계 체크
        var listAmt = $c.stf.getObjectValue(edt_ListAmt);
        if ($c.stf.getObjectValue(edt_EqmtFnd) != '' ||
            $c.stf.getObjectValue(edt_RefundFnd) != '' ||
            $c.stf.getObjectValue(edt_OperFnd) != '' ||
            $c.stf.getObjectValue(edt_MiscFnd) != '') {
            var eqmtAmt = $c.stf.getObjectValue(edt_EqmtFnd);
            if (eqmtAmt == '') eqmtAmt = 0;
            var refundAmt = $c.stf.getObjectValue(edt_RefundFnd);
            if (refundAmt == '') refundAmt = 0;
            var operAmt = $c.stf.getObjectValue(edt_OperFnd);
            if (operAmt == '') operAmt = 0;
            var miscAmt = $c.stf.getObjectValue(edt_MiscFnd);
            if (miscAmt == '') miscAmt = 0;
            var fndAmt = parseInt(eqmtAmt) + parseInt(refundAmt) + parseInt(operAmt) + parseInt(miscAmt);
            if (listAmt != fndAmt) {
                $c.win.alert('발행용도 금액 총계를 확인하십시오.');
                tab_Detail.setSelectedTabIndex(1);
                if ($c.stf.getObjectValue(edt_EqmtFnd) != '') {
                    edt_EqmtFnd.focus();
                    return 1;
                } else if ($c.stf.getObjectValue(edt_RefundFnd) != '') {
                    edt_RefundFnd.focus();
                    return 1;
                } else if ($c.stf.getObjectValue(edt_OperFnd) != '') {
