        var udwrt1Amt = 0;
        var udwrt2Amt = 0;
        var udwrt3Amt = 0;
        var udwrt4Amt = 0;
        var udwrt5Amt = 0;
        if (udwrt1 != '') {
            udwrt1Amt = $c.stf.getObjectValue(edt_UdwrtAmt1);
            if (udwrt2 == udwrt1) {
