            }
        } else {
            if ($c.stf.getObjectValue(edt_UdwrtAmt1) != '') {
                $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd1.focus();
                return 1;
            }
        }
        if (udwrt2 != '') {
            udwrt2Amt = $c.stf.getObjectValue(edt_UdwrtAmt2);
            if (udwrt1 == udwrt2) {
                isHas = true;
            } else if (udwrt3 == udwrt2) {
                isHas = true;
            } else if (udwrt4 == udwrt2) {
                isHas = true;
            }
            if ($c.stf.getObjectValue(edt_UdwrtAmt2) == '') {
                $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt2.focus();
                return 1;
            }
        } else {
            if ($c.stf.getObjectValue(edt_UdwrtAmt2) != '') {
                $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd2.focus();
                return 1;
            }
        }
        if (udwrt3 != '') {
            udwrt3Amt = $c.stf.getObjectValue(edt_UdwrtAmt3);
            if (udwrt1 == udwrt3) {
                isHas = true;
            } else if (udwrt2 == udwrt3) {
                isHas = true;
            } else if (udwrt4 == udwrt3) {
                isHas = true;
            }
            if ($c.stf.getObjectValue(edt_UdwrtAmt3) == '') {
