                return 1;
            }
        }
        if (udwrt4 != '') {
            udwrt4Amt = $c.stf.getObjectValue(edt_UdwrtAmt4);
            if (udwrt1 == udwrt4) {
                isHas = true;
            } else if (udwrt2 == udwrt4) {
                isHas = true;
            } else if (udwrt3 == udwrt4) {
                isHas = true;
            }
            if ($c.stf.getObjectValue(edt_UdwrtAmt4) == '') {
                $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt4.focus();
