        //인수금액 총계 체크
        udwrt5Amt = $c.stf.getObjectValue(edt_UdwrtAmt5);
        if (udwrt5Amt == '') udwrt5Amt = 0;
        var udwrtAmt = parseInt(udwrt1Amt) + parseInt(udwrt2Amt) + parseInt(udwrt3Amt) + parseInt(udwrt4Amt) + parseInt(udwrt5Amt);
