                $c.win.alert('인수금액 총계를 확인하십시오.');
                tab_Detail.setSelectedTabIndex(2);
                if ($c.stf.getObjectValue(edt_UdwrtAmt1) != '') {
                    edt_UdwrtAmt1.focus();
                    return 1;
                } else if ($c.stf.getObjectValue(edt_UdwrtAmt2) != '') {
                    edt_UdwrtAmt2.focus();
                    return 1;
                } else if ($c.stf.getObjectValue(edt_UdwrtAmt3) != '') {
                    edt_UdwrtAmt3.focus();
                    return 1;
                } else if ($c.stf.getObjectValue(edt_UdwrtAmt4) != '') {
                    edt_UdwrtAmt4.focus();
                    return 1;
                } else if ($c.stf.getObjectValue(edt_UdwrtAmt5) != '') {
                    edt_UdwrtAmt5.focus();
                    return 1;
                }
            }
        }

        //변동금리탭 이자율변경 정보
        var rowCnt = dts_ChgInt.getTotalRow();
        for (var idx = 1; idx <= rowCnt; idx++) {
            if (dts_ChgInt.getCellData(idx, 'INT_RT_CHG_DD').length != 8) {
                $c.win.alert('변동금리탭 이자율결정 기준일 정보를 확인하여 주십시요.');
                dts_ChgInt.setRowPosition(idx, 0);
                return 1;
            }
        }

        //옵션탭 Call
        if (scwin.fn_chkCall() > 0) return 1;

        //옵션탭 Put
        if (scwin.fn_chkPut() > 0) return 1;

        //분할상환체크
        rowCnt = dts_SplitRedmpt.getTotalRow();
        for (var idx = 1; idx <= rowCnt; idx++) {
            if (dts_SplitRedmpt.getCellData(idx, 'INT_PAY_DD').length != 8) {
                $c.win.alert('분할상환탭 불균등 정보를 확인하여 주십시요.');
                dts_SplitRedmpt.setRowPosition(idx, 0);
                return 1;
            }
        }

        //원리금정보
        rowCnt = dts_Princint.getTotalRow();
        for (var idx = 1; idx <= rowCnt; idx++) {
            if (dts_Princint.getCellData(idx, 'INT_PAY_DD').length != 8) {
                $c.win.alert('원리금탭 정보를 확인하여 주십시요.');
                dts_Princint.setRowPosition(idx, 0);
                return 1;
            }
        }

        // 분리형BW여부가 체크가 안된 경우만 메세지 확인함. jackal_181210
        if (!chk_DetachBwYn.checked) {
            if ($c.stf.getObjectValue(cmb_StkRelCorpbndRghtTpCd) != '' &&
                $c.stf.getObjectValue(cmb_NusualBndTpCd) != '2') {
                msg = "" + "특이채권유형이 " + $c.stf.fn_getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "\n주식관련탭의 권리구분이 [" + $c.stf.fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "\n" + "\n주식관련탭의 권리구분은 주식관련사채일때만 입력가능한 항목입니다." + "\n그래도 작업을 계속하시겠습니까?";
                if (!window.confirm(msg)) return 1;
            }
        }

        //ELB등 
        if ($c.stf.getObjectValue(cmb_NusualBndTpCd) == '3' ||
            $c.stf.getObjectValue(cmb_NusualBndTpCd) == '4') {
            if ($c.stf.getObjectValue(edt_PrincGrtRt) == '') {
                $c.win.alert("원금보장율을 입력하십시오.");
                return 1;
            }
        } else if ($c.stf.getObjectValue(edt_PrincGrtRt) == '') {
            if ($c.stf.getObjectValue(cmb_NusualBndTpCd) == '3' ||
                $c.stf.getObjectValue(cmb_NusualBndTpCd) == '4') {
                $c.win.alert("ELB등 탭은 ELS/DLS채권시에만 입력합니다. 특이채권유형을 확인바랍니다.");
                return 1;
            }
        }
        if (dts_IsuInfo.getCellData(1, "INT_PAY_METHD_CD") == '' ||
            dts_IsuInfo.getCellData(1, "INT_PAY_METHD_CD").substring(0, 1) == '1') {
            if (dts_IsuInfo.getCellData(1, "INT_RT_DECSN_MISC_BAS_INT_NM") != '') {
                $c.win.alert("변동금리탭은 변동금리시에만 입력합니다. 이자지급방법을 확인바랍니다.");
                return 1;
            }
        }
        if (dts_IsuInfo.getCellData(1, "IMBDOPT_CORPBND_CD") == '' &&
            (dts_OptionCall.getTotalRow() > 0 || dts_OptionPut.getTotalRow() > 0)) {
            $c.win.alert("CALL/PUT 탭은 옵션일 경우에만 입력합니다. 옵션구분을 확인바랍니다.");
            return 1;
        }
        if (dts_IsuInfo.getCellData(1, "ASST_SECUTIZ_TP_CD") == '' &&
            dts_IsuInfo.getCellData(1, "SECUTIZ_ADM_INST_CD").substring(0, 1) == '1') {
            $c.win.alert("유동화탭은 유동화 채권일 경우에만 입력합니다. 유동화채권 인지 확인바랍니다.");
            return 1;
        }
        if (!$c.stf.checkMaxLength(txb_IntRtDecsnMiscBasIntNm, 20, '기타기준금리')) return 1;
        if (!$c.stf.checkMaxLength(txb_NusualIsuCondContn, 60, '특이발행조건(외부용)')) return 1;
        if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '기타참고사항(내부용)')) return 1;
        if (!$c.stf.checkMaxLength(txb_UlyContn, 100, '기초자산상세내용')) return 1;
        if (!$c.stf.checkMaxLength(txb_ElsCondContn1, 100, '조건내용1')) return 1;
        if (!$c.stf.checkMaxLength(txb_ElsCondContn2, 100, '조건내용2')) return 1;

        // jackal_16.10.11  call put 사유 길이 체크 추가
        if (!$c.stf.checkMaxLength(txb_CallExerRsn, 50, '콜 사유')) return 1;
        if (!$c.stf.checkMaxLength(txb_PutExerRsn, 50, '풋 사유')) return 1;

        //국고채만 스트립미분리잔액 입력가능
        if (scwin.vMktactCd == '111' &&
            $c.stf.getObjectValue(cmb_InfllnkYn) != 'Y' &&
            dts_IsuInfo.getCellData(1, "ISU_NM").indexOf("변동") == -1) {
            if (dts_IsuInfo.getCellData(1, "ISUR_CD") == 'GB035' &&
                $c.stf.getObjectValue(cmb_BndStripTpCd) == '1') {
                var num_iss_dt = $c.stf.getObjectValue(edt_IsuDd);
                var expr_term = ($c.stf.getObjectValue(edt_RedmptDd) - $c.stf.getObjectValue(edt_IsuDd)) / 10000;

                // 2006년 이후 발행된 만기 5년이상 국고채권만 미분류 잔액이 존재
                // jackal_150714 3년물이상으로 변경되었는데 여태 수정이 안되어 있었슴. expr_term 5을 3을 수정
                if (num_iss_dt >= 20060101 && expr_term >= 3) {
                    $c.win.alert('스트립미분리잔액을 상장금액으로 자동설정합니다.');
                    $c.stf.setObjectValue(edt_StripNsprtBal, $c.stf.getObjectValue(edt_ListAmt));
                } else {
                    $c.stf.setObjectValue(edt_StripNsprtBal, '');
                }
            }
        } else {
            $c.stf.setObjectValue(edt_StripNsprtBal, '');
        }

        //환율적용 발행금액,상장금액 체크
        if ($c.stf.getObjectValue(cmb_CurrTpCd) != '' &&
            $c.stf.getObjectValue(cmb_CurrTpCd) != '1') {
            var isuAmt = $c.stf.getObjectValue(edt_IsuAmt);
            var listAmt = $c.stf.getObjectValue(edt_ListAmt);
            if (isuAmt == '') isuAmt = 0;
            if (listAmt == '') listAmt = 0;
            var exchrt = $c.bns.fn_SearchExchrt(scwin.vScrenID, dts_CheckExa, $c.stf.getObjectValue(cmb_CurrTpCd), '1');
            isuAmt = isuAmt * exchrt;
            listAmt = listAmt * exchrt;

            //메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
            if (parseInt(isuAmt) < parseInt(listAmt)) {
                $c.win.alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
                return 1;
            }
            if (isuAmt <= 100000000) {
                $c.win.alert("발행금액이 1억원 이하입니다.");
            } else if (isuAmt >= 1000000000000) {
                $c.win.alert("발행금액이 1조원 이상입니다.");
            }
            if (listAmt <= 100000000) {
                $c.win.alert("상장금액이 1억원 이하입니다.");
            } else if (listAmt >= 1000000000000) {
                $c.win.alert("상장금액이 1조원 이상입니다.");
            }
        }

        // 분리형BW여부가 체크는 특이채권유형이 일반채권인 경우만 체크가능 jackal_181210
        if (chk_DetachBwYn.checked) {
            if ($c.stf.getObjectValue(cmb_NusualBndTpCd) != '1') {
                msg = "" + "분리형BW가 체크된 경우 특이채권유형이 [1 일반채권] 이어야 합니다." + "\n특이채권유형이 [" + $c.stf.fn_getComboTextValue(cmb_NusualBndTpCd) + "]로 입력되어 있습니다.";
                $c.win.alert(msg);
                return 1;
            }
        }


        //  분리형BW여부가 체크되어 있스면 권리구분이 21 이어야 하고 jackal_181210
        if (chk_DetachBwYn.checked) {
            // 주식관련 권리구분 21 setting
            if ($c.stf.getObjectValue(cmb_StkRelCorpbndRghtTpCd) != '21') {
                msg = "" + "분리형BW가 체크된 경우 주식관련탭의 권리구분이 [21 신주인수권(분리형)] 이어야 합니다. " + "\n주식관련탭의 권리구분이 [" + $c.stf.fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다.";
                $c.win.alert(msg);
                return 1;
            }
        }

        // 더불어 특이채권유형이 2(주권관련채권) 이면 21은 선택 못하게 해야 함. jackal_181210
        if ($c.stf.getObjectValue(cmb_NusualBndTpCd) == '2') {
            if ($c.stf.getObjectValue(cmb_StkRelCorpbndRghtTpCd) == '21') {
                msg = "" + "특이채권유형이 " + $c.stf.fn_getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "\n주식관련탭의 권리구분이 [" + $c.stf.fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "\n" + "\n이 권리구분은 일반채권 분리형BW가 체크 되었을때만 입력가능한 항목입니다.";
                $c.win.alert(msg);
                return 1;
            }
        }

        //이자지급방법이 변동금리형이면
        if ($c.stf.getObjectValue(cmb_IntPayMethdCd) > 20) {
            // 금리결정기준일 1~10 일까지 만 입력 체크   JACKAL_190509
            var vIntDecsnBasDys = $c.stf.getObjectValue(edt_IntDecsnBasDys);
            if (vIntDecsnBasDys != '' && (vIntDecsnBasDys > 10 || vIntDecsnBasDys < 1)) {
                if (!window.confirm('변동금리 탭의 이자지급기준일로부터 금리결정기준일은 1 ~ 10 일전 까지만 선택가능합니다.\n그래도 처리하시겠습니까?')) return 1;
            }
        }
    }
    return 0;
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //종목정보체크
    if ($c.bns.fn_CheckNewListIsuInfoWIT(dts_IsuInfo) > 0) return;
    if (scwin.fn_CheckEach() > 0) return;
    if (scwin.processGp == '4') {
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.vBndApplId) > 0) return;
    }
    //채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if ($c.bns.fn_ChkBndClssAndIsur(scwin.vScrenID, dts_IsuInfo, scwin.vMktactCd) > 0) return;
    //수수료체크
    if ($c.bns.fn_CheckFee(scwin.vScrenID, '1', dts_CheckCmData, scwin.vBndApplId) > 0) return;
    //처리완료,수정
    var hasAttachDoc = dts_IsuInfo.getCellData(1, "HAS_ATTACH_DOC");
    if (scwin.processGp == '4') {
        //if(! fn_EndConfirm(hasAttachDoc, '수정')) return;		
        if (!$c.bns.fn_EndConfirm1(scwin.vScrenID, dts_Temp, scwin.vBndApplId, scwin.vBndListProcsTpCd, '수정')) return;
    } else {
        //적용일,매매일,마감일,채권마감 체크
        if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.vBndApplId) > 0) return;
        //if(fn_CheckCmData(vScrenID, dts_CheckCmData, vStrtDd, vBndApplId) > 0)  return;
        //if(! fn_EndConfirm(hasAttachDoc, '처리완료')) return;				
        if (!$c.bns.fn_EndConfirm1(scwin.vScrenID, dts_Temp, scwin.vBndApplId, scwin.vBndListProcsTpCd, '처리완료')) return;
    }

    //발행방법설정

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    var ISU_METHD_INDIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_INDIRECT');
    var ISU_METHD_DIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_DIRECT');
    var ISU_METHD_PPBOND = dts_IsuInfo.getCellData(1, 'ISU_METHD_PPBOND');
    dts_IsuInfo.setCellData(1, 'BND_ISU_METHD_CD', /*ORG SRC: dts_IsuInfo.setNameValue(1, 'BND_ISU_METHD_CD', dts_IsuInfo.NameValue(1, 'BND_ISU_METHD_CD') = );*/ X = X);

    // 분리형BW여부 설정 jackal_181210

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    var DETACH_BW_YN = dts_IsuInfo.getCellData(1, 'DETACH_BW_YN');
    if (DETACH_BW_YN == '1') dts_IsuInfo.setCellData(1, 'DETACH_BW_YN', /*ORG SRC: dts_IsuInfo.setNameValue(1, 'DETACH_BW_YN', dts_IsuInfo.NameValue(1, 'DETACH_BW_YN') = );*/ X = X);


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    else dts_IsuInfo.setCellData(1, 'DETACH_BW_YN', /*ORG SRC: dts_IsuInfo.setNameValue(1, 'DETACH_BW_YN', dts_IsuInfo.NameValue(1, 'DETACH_BW_YN') = );*/ X = X);

    //탭 데이터셋 설정
    scwin.fn_SetCreditData();
    scwin.fn_SetUdwrtInstData();
    scwin.fn_SetSecutizAsstData();
    scwin.fn_SetBasIntRtData();

    //변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    dts_IsuInfo.UseChangeInfo = "False";
    dts_OptionCall.UseChangeInfo = "False";
    dts_OptionPut.UseChangeInfo = "False";
    dts_Princint.UseChangeInfo = "False";
    dts_SplitRedmpt.UseChangeInfo = "False";
    dts_ChgInt.UseChangeInfo = "False";
    // 주식관련 행사가격 조정 JACKAL_190220
    dts_StockRel.UseChangeInfo = "False";
    var url = "/bns/NewList.do?method=processAcptProcessComplt";
    if (scwin.processGp == '4') {
        url = "/bns/NewList.do?method=updateAcpt";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    param += ", STRT_DD=" + dts_IsuInfo.getCellData(1, "STRT_DD");
    param += ", STD_CD=" + dts_IsuInfo.getCellData(1, "STD_CD");
    dts_IsuInfo.setCellData(1, 'COUPN_RT_DECSN_BAS_INT_CD', $c.stf.getObjectValue(cmb_CoupnRtDecsnBasIntCd));
    var dsKeyValue = "JSP(";
    dsKeyValue += "I:pInput=dts_IsuInfo";
    dsKeyValue += ", I:pInput1=dts_Credit";
    dsKeyValue += ", I:pInput2=dts_UdwrtInst";
    dsKeyValue += ", I:pInput3=dts_CoupnRtAndIsurPrc";
    dsKeyValue += ", I:pInput4=dts_Princint";
    dsKeyValue += ", I:pInput5=dts_OptionCall";
    dsKeyValue += ", I:pInput6=dts_OptionPut";
    dsKeyValue += ", I:pInput7=dts_ChgInt";
    dsKeyValue += ", I:pInput8=dts_SplitRedmpt";
    dsKeyValue += ", I:pInput9=dts_SecutizAsst";
    dsKeyValue += ", I:pInput10=dts_StockRel"; // 주식관련 행사가격조정 JACKAL_190220
    dsKeyValue += ")";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = dsKeyValue;
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SetCreditData
 * 설명       : 신용평가 데이터셋 설정
 ***********************************************/
scwin.fn_SetCreditData = function() {
    dts_Credit.removeAll();
    if ($c.stf.getObjectValue(cmb_CreditValuInstCd1) != '') {
        dts_Credit.insertRow();
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_APPL_ID', scwin.vBndApplId);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'CREDIT_VALU_INST_CD', $c.stf.getObjectValue(cmb_CreditValuInstCd1));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BYINST_CREDIT_VALU_GRD', $c.stf.getObjectValue(cmb_ByinstCreditValuGrd1));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'SF_VALU_YN', $c.stf.getObjectValue(cmb_SfValuYn1));
    }
    if ($c.stf.getObjectValue(cmb_CreditValuInstCd2) != '') {
        dts_Credit.insertRow();
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_APPL_ID', scwin.vBndApplId);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'CREDIT_VALU_INST_CD', $c.stf.getObjectValue(cmb_CreditValuInstCd2));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BYINST_CREDIT_VALU_GRD', $c.stf.getObjectValue(cmb_ByinstCreditValuGrd2));
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'SF_VALU_YN', $c.stf.getObjectValue(cmb_SfValuYn2));
    }
    if ($c.stf.getObjectValue(cmb_CreditValuInstCd3) != '') {
        dts_Credit.insertRow();
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_APPL_ID', scwin.vBndApplId);
        dts_Credit.setCellData(dts_Credit.getRowPosition(), 'BND_LIST_PROCS_TP_CD', scwin.vBndListProcsTpCd);
