/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //종목정보체크
    if ($c.bns.fn_CheckNewListIsuInfoWIT(dts_IsuInfo) > 0) return;
    if (scwin.fn_CheckEach() > 0) return;
    //적용일,매매일,마감일,채권마감 체크
    if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.vBndApplId) > 0) return;
    //if(fn_CheckCmData(vScrenID, dts_CheckCmData, vStrtDd, vBndApplId) > 0)  return;
    //채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if ($c.bns.fn_ChkBndClssAndIsur1(scwin.vScrenID, dts_IsuInfo, scwin.vMktactCd) > 0) return;

    //접수
    var hasAttachDoc = dts_IsuInfo.getCellData(1, "HAS_ATTACH_DOC");
    //if(! fn_EndConfirm(hasAttachDoc, '접수')) return;
    if (!$c.bns.fn_EndConfirm1(scwin.vScrenID, dts_Temp, scwin.vBndApplId, scwin.vBndListProcsTpCd, '접수')) return;

    //수수료 팝업호출
    scwin.fn_GetPar = fn_GetParNewListFee;
    scwin.fn_SetPar = fn_SetParNewListFee;
    $c.bns.fn_PopNewListFee(grd_ApplList);
    if (scwin.vRegYn != "Y") return;

    //변경된 데이터가 없더라도 데이터셋 전송하여 처리 진행
    dts_Fee.UseChangeInfo = "False";
    var url = "/bns/NewList.do?method=processAcptWIT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    param += ", STRT_DD=" + dts_IsuInfo.getCellData(1, "STRT_DD");
    dts_IsuInfo.setCellData(1, 'COUPN_RT_DECSN_BAS_INT_CD', $c.stf.getObjectValue(cmb_CoupnRtDecsnBasIntCd));
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo, I:pInput1=dts_Fee)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};



