    $c.stf.setObjectValue(cbHdTpObj, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_TP_CD'));
    $c.stf.setObjectValue(txb_AsstHdTpMiscContn, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_TP_MISC_CONTN'));

    //자산보유자기관
    var cbdata = '';
    cbdata = "^ ," + dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_CD') + "^" + dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_NM');
    cbHdInstObj.CBData = cbdata;
    $c.stf.setObjectValue(cbHdInstObj, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_CD'));
    $c.stf.setObjectValue(txb_AsstHdInstMiscContn, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_MISC_CONTN'));

    //자산관리자기관
    cbdata = "^ ," + dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_CD') + "^" + dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_NM');
