    $c.stf.setObjectValue(cbAdmObj, dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_CD'));
    $c.stf.setObjectValue(txb_AsstAdmInstMiscContn, dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_MISC_CONTN'));
};


/********************************************** 
 * 함수명   : fn_SetBtn
 * 설명       : 버튼보이기를 설정한다.
 ***********************************************/
scwin.fn_SetBtn = function() {
    if (scwin.vBndListProcsTpCd == 1) {
        $c.stf.showObj(btn_StdCdReq, false);
        return;
    }
    if ($c.stf.getObjectValue(txb_StdCd) == '') {
        $c.stf.showObj(btn_StdCdReq, true);
        btn_ProcsComplt.src = '../img/bns/btn_20_d.gif';
        btn_ProcsComplt.setDisabled(true);
        btn_TeamleadrConfrm.src = '../img/bns/btn_21_d.gif';
        btn_TeamleadrConfrm.setDisabled(true);
    } else {
        $c.stf.showObj(btn_StdCdReq, false);
        if (scwin.vProcsStatCd == "2") {
            btn_ProcsComplt.src = '../img/bns/btn_20_d.gif';
            btn_ProcsComplt.setDisabled(true);
            btn_TeamleadrConfrm.src = '../img/bns/btn_21.gif';
            btn_TeamleadrConfrm.setDisabled(false);
        } else {
            btn_ProcsComplt.src = '../img/bns/btn_20.gif';
            btn_ProcsComplt.setDisabled(false);
            btn_TeamleadrConfrm.src = '../img/bns/btn_21_d.gif';
            btn_TeamleadrConfrm.setDisabled(true);
        }
    }
};




