    $c.stf.setObjectValue(cmb_BndUdwrtInstCd1, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd2, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd3, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd4, '');
