    if (scwin.vBndListProcsTpCd == '2') {
        chk_DetachBwYn.setDisabled(false);
        chk_IsuMethdIndirect.setDisabled(false);
        chk_IsuMethdDirect.setDisabled(false);
        chk_IsuMethdPpbond.setDisabled(false);
        txb_NusualIsuCondContn.setDisabled(false);
        txb_MemoContn.setDisabled(false);
