/**
 * 기준금리상세 첫번째 콤보 onChange
 */
scwin.fn_CtrlFrnBasIntTpCd1 = function() {
    // 콤보 데이터 필터링
    scwin.fn_FilterComboValue();

    // 콤보 활성비활성, 보이고 안보이고 세팅
    if (tab_List.getSelectedTabIndex() == 1) {
        scwin.fn_CtrlObject1_1();
    } else {
        scwin.fn_CtrlObject1_2();
    }
};



/**
 * 기준금리상세 세번째 콤보 onChange
 *    - 기타상세 항목 활성/비활성
 */
scwin.fn_CtrlFrnBasIntTpCd3 = function() {
    var frnBasIntTpCd3 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd3);
    // 콤보3의 기타 -- 상세입력만 활성
    if (frnBasIntTpCd3 == "2Z" || frnBasIntTpCd3 == "3Z" || frnBasIntTpCd3 == "4Z" || frnBasIntTpCd3 == "5Z") {
        txb_FrnBasIntMisc.setDisabled(false);
    } else {
        txb_FrnBasIntMisc.setDisabled(true); //기타는 기본값 비활성

    }
};



/**
 * 기준금리 2~4번째 콤보 필터링
 */
scwin.fn_FilterComboValue = function() {
    var frnBasIntTpCd1 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd1);
    dts_FrnBasIntTpCd2.Filter();
    dts_FrnBasIntTpCd3.Filter();
    dts_FrnBasIntTpCd4.Filter();

    // 관련 항목 기본값 세팅
    cmb_FrnBasIntTpCd2.setSelectedIndex(0);
    cmb_FrnBasIntTpCd3.setSelectedIndex(0);
    cmb_FrnBasIntTpCd4.setSelectedIndex(0);
};


/**
 * 신청내역 탭에서 기준금리상세 항목 컨트롤
 * 신청내역 탭에서는 전부 비활성...
 */
scwin.fn_CtrlObject1_1 = function() {
    var frnBasIntTpCd1 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd1);

    // 일단 전부 활성화
    cmb_FrnBasIntTpCd2.setDisabled(true);
    cmb_FrnBasIntTpCd3.setDisabled(true);
    cmb_FrnBasIntTpCd4.setDisabled(true);
    txb_FrnBasIntMisc.setDisabled(true); //기타 비활성

    $c.stf.showObj(cmb_FrnBasIntTpCd2, true);
    $c.stf.showObj(txb_FrnBasIntTp2, false);
    $c.stf.showObj(img_isurCd, false);

    // 시가평가수익률(발행기관), 콤보2 안보이고 발행기관입력팝업 보이고..
    if (frnBasIntTpCd1 == "4") {
        $c.stf.showObj(cmb_FrnBasIntTpCd2, false);
        $c.stf.showObj(txb_FrnBasIntTp2, true);
    }
};



/**
 * 접수내역 탭에서 기준금리상세 항목 컨트롤
 */
scwin.fn_CtrlObject1_2 = function() {
    var frnBasIntTpCd1 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd1);

    // 일단 전부 활성화
    cmb_FrnBasIntTpCd2.setDisabled(false);
    cmb_FrnBasIntTpCd3.setDisabled(false);
    cmb_FrnBasIntTpCd4.setDisabled(false);
    //txb_FrnBasIntMisc.disabled = true;  //기타는 비활성

    $c.stf.showObj(cmb_FrnBasIntTpCd2, true);
    $c.stf.showObj(txb_FrnBasIntTp2, false);
    $c.stf.showObj(img_isurCd, false);

    // 최종호가수익률
    if (frnBasIntTpCd1 == "1") {
        cmb_FrnBasIntTpCd4.setDisabled(true);

        // 시가평가수익률(CD/CP), 시가평가수익률(채권그룹), 워노하이자율스왑

    } else if (frnBasIntTpCd1 == "2" || frnBasIntTpCd1 == "3" || frnBasIntTpCd1 == "5") {
        // nothing to do


        // 시가평가수익률(발행기관), 콤보2 안보이고 발행기관입력팝업 보이고..

    } else if (frnBasIntTpCd1 == "4") {
        $c.stf.showObj(cmb_FrnBasIntTpCd2, false);
        $c.stf.showObj(txb_FrnBasIntTp2, true);
        $c.stf.showObj(img_isurCd, true);

        // KOFR금리 -- 전부 비활성

    } else if (frnBasIntTpCd1 == "6") {
        cmb_FrnBasIntTpCd2.setDisabled(true);
        cmb_FrnBasIntTpCd3.setDisabled(true);
        cmb_FrnBasIntTpCd4.setDisabled(true);

        // 기타 -- 상세입력빼고 전부 비활성

    } else if (frnBasIntTpCd1 == "7") {
        cmb_FrnBasIntTpCd2.setDisabled(true);
        cmb_FrnBasIntTpCd3.setDisabled(true);
        cmb_FrnBasIntTpCd4.setDisabled(true);
        txb_FrnBasIntMisc.setDisabled(false); // 상세입력만 활성

    }
};



/********************************************** 
 * 함수명   : fn_ShowIsurPopup
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsurPopup = function(obj) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(obj);
};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_FrnBasIntTpCd2),
        ISUR_NM: $c.stf.getObjectValue(txb_FrnBasIntTp2)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_FrnBasIntTpCd2, arrPar[0].ISUR_CD);
    $c.stf.setObjectValue(txb_FrnBasIntTp2, arrPar[0].ISUR_NM);
};
