scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vRowCount = 0;
    scwin.fn_ClearIsuInfo();
    scwin.vBndListProcsTpCd = nIndex;
    $c.stf.showObj(txb_Dtl1, false);
    $c.stf.showObj(txb_Dtl, true);
    if (scwin.vBndListProcsTpCd == 2) {
        txb_Dtl.setValue("접수내역");
    } else {
        txb_Dtl.setValue("신청내역");
    }
    scwin.fn_ChgStatComp();
    //  국채인 경우만 발행전국채거래구분코드 수정가능  jackal_150127
    scwin.fn_PresaleGovbndTrdTpCd();
    scwin.fn_list_sync();
    scwin.fn_SetDtlTab();
};
scwin.dts_List_OnRowPosChanged = function(row) {
