        cmb_InfllnkYn.setDisabled(false);
        edt_IsuDdRefIdx.setDisabled(false);
    } else {
        cmb_InfllnkYn.setDisabled(true);
        edt_IsuDdRefIdx.setDisabled(true);
    }

    //한글금액표기
    $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));

    //금액여분적용
    scwin.fn_SetMargin();
    if (rowcount == 0) return;
    var lbl = $c.stf.getObjectValue(txb_Dtl);
    if (dts_IsuInfo.getCellData(1, 'STD_CD') != '') {
        var isuNm = dts_IsuInfo.getCellData(1, 'STD_REF_DTL');
        $c.stf.setObjectValue(txb_Dtl1, lbl + isuNm);
        $c.stf.showObj(txb_Dtl, false);
        $c.stf.showObj(txb_Dtl1, true);
    } else {
        $c.stf.showObj(txb_Dtl1, false);
        $c.stf.showObj(txb_Dtl, true);
    }

    //신용등급 SF
    if (scwin.vBndListProcsTpCd != '1' &&
        $c.stf.getObjectValue(cmb_AsstSecutizTpCd) == '') {
        $c.stf.setObjectValue(cmb_SfValuYn1, '');
        $c.stf.setObjectValue(cmb_SfValuYn2, '');
        $c.stf.setObjectValue(cmb_SfValuYn3, '');
        $c.stf.setObjectValue(cmb_SfValuYn4, '');
        cmb_SfValuYn1.setDisabled(true);
        cmb_SfValuYn2.setDisabled(true);
        cmb_SfValuYn3.setDisabled(true);
        cmb_SfValuYn4.setDisabled(true);
    }

    // 기준금리상세1의 값에다른 항목 활성/비활성 등 제어.
    // 콤보 활성비활성, 보이고 안보이고 세팅
    if (tab_List.getSelectedTabIndex() == 1) {
        scwin.fn_CtrlObject1_1();
    } else {
        scwin.fn_CtrlObject1_2();
    }
};
