scwin.cmb_IntPayMethdCd_OnSelChange2 = function() {
    var cd = $c.stf.getObjectValue(cmb_IntPayMethdCd);
    //이자지급방법이 변동금리형이면
    if (cd > 20) {
        //변동금리탭 설정
        cmb_IntRtDecsnMiscBasIntCd.setDisabled(false);
        txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
        $c.stf.setObjectValue(cmb_IntRtDecsnMiscBasIntCd, $c.stf.getObjectValue(cmb_CoupnRtDecsnBasIntCd));
        if ($c.stf.getObjectValue(cmb_CoupnRtDecsnBasIntCd) == '90') {
            txb_CoupnRtMiscBasIntContn.setDisabled(false);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
            if ($c.stf.getObjectValue(txb_IntRtDecsnMiscBasIntNm) != '' &&
                $c.stf.getObjectValue(txb_CoupnRtMiscBasIntContn) == '') {
                $c.stf.setObjectValue(txb_CoupnRtMiscBasIntContn, $c.stf.getObjectValue(txb_IntRtDecsnMiscBasIntNm));
            } else {
                $c.stf.setObjectValue(txb_IntRtDecsnMiscBasIntNm, $c.stf.getObjectValue(txb_CoupnRtMiscBasIntContn));
            }
        } else {
            $c.stf.setObjectValue(txb_IntRtDecsnMiscBasIntNm, '');
            $c.stf.setObjectValue(txb_CoupnRtMiscBasIntContn, '');
            txb_CoupnRtMiscBasIntContn.setDisabled(true);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
        }
    } else {
        //변동금리탭 클리어
        $c.stf.setObjectValue(cmb_IntRtDecsnMiscBasIntCd, '');
        $c.stf.setObjectValue(txb_IntRtDecsnMiscBasIntNm, '');
        $c.stf.setObjectValue(cmb_SpdSgn, '');
        $c.stf.setObjectValue(edt_Spd, '');
        $c.stf.setObjectValue(cmb_IntRtDecsnTmCd, '');
        $c.stf.setObjectValue(edt_UplmtCoupnRt, '');
        $c.stf.setObjectValue(edt_LwlmtCoupnRt, '');
        $c.stf.setObjectValue(edt_IntRtDecsnBasDd, '');
        dts_ChgInt.removeAll();
        cmb_IntRtDecsnMiscBasIntCd.setDisabled(true);
        txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
        //txb_CoupnRtMiscBasIntContn.disabled = true;

        // 변동금리 추가항목 클리어 JACKAL_190509
        $c.stf.setObjectValue(cmb_IntDecsnRegulYn, '');
        $c.stf.setObjectValue(txb_IntDecsnNregulRsnContn, '');
        $c.stf.setObjectValue(cmb_IntDecsnBasTpCd, '');
        $c.stf.setObjectValue(edt_IntDecsnBasDys, '');
        $c.stf.setObjectValue(edt_IntPayCnt, '');
    }
};
