scwin.btn_ChgIntRtAutoInsert_onclick = function() {
    var cd = $c.stf.getObjectValue(cmb_IntDecsnRegulYn);

    //상환방법: 영구채 선택시 비정기 선택해야 함. JACKAL_190509
    if ($c.stf.getObjectValue(cmb_RedmptMethdTpCd) == "3") {
        // 금리결정 정기이면  
        if (cd == 'Y') {
            $c.win.alert("상환방법이 영구채 일 경우 금리결정정기여부를 비정기로 선택하여야 합니다.");
            return;
        }
    }

    // 금리결정기준일 1~10 일까지 만 입력 체크   JACKAL_190509
    var vIntDecsnBasDys = $c.stf.getObjectValue(edt_IntDecsnBasDys);
    if (vIntDecsnBasDys > 10 || vIntDecsnBasDys < 1) {
        $c.win.alert('변동금리 탭의 이자지급기준일로부터 금리결정기준일은 1 ~ 10 일전 까지만 선택가능합니다.');
        return;
    }

    //변동금리 자동입력 JACKAL_190509 
    scwin.fn_ChgIntRtAutoInput();
};
scwin.cmb_IntDecsnRegulYn_OnSelChange = function() {
    //alert('cmb_IntDecsnRegulYn.OnSelChange()');

    var cd = $c.stf.getObjectValue(cmb_IntDecsnRegulYn);
    // 행사가격 조정 해당사항이면 
    if (cd == 'Y') {
        txb_IntDecsnNregulRsnContn.setDisabled(true);
        $c.stf.setObjectValue(txb_IntDecsnNregulRsnContn, '');
    } else {
        txb_IntDecsnNregulRsnContn.setDisabled(false);
    }

    //상환방법: 영구채 선택시 비정기 선택해야 함. JACKAL_190509
    if ($c.stf.getObjectValue(cmb_RedmptMethdTpCd) == "3") {
        // 금리결정 정기이면  
        if (cd == 'Y') {
            $c.win.alert("상환방법이 영구채 일 경우 금리결정정기여부를 비정기로 선택하여야 합니다.");
            return;
        }
    }
};
