scwin.dts_FrnBasIntTpCd2_OnFilter = function(row) {
    var frnBasIntTpCd1 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd1);
    if (dts_FrnBasIntTpCd2.getCellData(row, "VALUE").substr(0, 1) == frnBasIntTpCd1) {
        return true;
    } else {
        return false;
    }
};
scwin.dts_FrnBasIntTpCd3_OnFilter = function(row) {
    var frnBasIntTpCd1 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd1);
    if (dts_FrnBasIntTpCd3.getCellData(row, "VALUE").substr(0, 1) == frnBasIntTpCd1) {
        return true;
    } else {
        return false;
    }
};
scwin.dts_FrnBasIntTpCd4_OnFilter = function(row) {
    var frnBasIntTpCd1 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd1);
    if (frnBasIntTpCd1 == "1" || frnBasIntTpCd1 == "6" || frnBasIntTpCd1 == "7") {
        return false;
    } else if (frnBasIntTpCd1 == "2" || frnBasIntTpCd1 == "3" || frnBasIntTpCd1 == "4") {
        if (dts_FrnBasIntTpCd4.getCellData(row, "VALUE").substr(0, 1) == "0") {
            return true;
        } else {
            return false;
        }
    } else if (frnBasIntTpCd1 == "5") {
        if (dts_FrnBasIntTpCd4.getCellData(row, "VALUE").substr(0, 1) == frnBasIntTpCd1) {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
};
