scwin.cmb_FrnBasIntTpCd1_OnCloseUp = function() {
    $c.stf.setObjectValue(txb_FrnBasIntTp2, "");
    $c.stf.setObjectValue(txb_FrnBasIntMisc, "");
    var frnBasIntTpCd1 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd1);
    if (frnBasIntTpCd1 == "6" || frnBasIntTpCd1 == "7") {
        $c.stf.setObjectValue(txb_FrnBasIntTpCd2, "");
    }
};
scwin.cmb_FrnBasIntTpCd3_OnCloseUp = function() {
    var frnBasIntTpCd3 = $c.stf.getObjectValue(cmb_FrnBasIntTpCd3);
    if (frnBasIntTpCd3 != '2Z' && frnBasIntTpCd3 != '3Z' && frnBasIntTpCd3 != '4Z' && frnBasIntTpCd3 != '5Z') {
        $c.stf.setObjectValue(txb_FrnBasIntMisc, "");
    }
};
